/* ---- helpers ---- */
function svcView(o,s){return {...s,owner:o,oid:o.id}}
function allServices(){const out=[];[...D().svc,...D().biz].forEach(o=>{if(o.status!=='approved')return;(o.services||[]).forEach(s=>{if(s.active!==false)out.push(svcView(o,s))})});return out}
function svcObj(id){const o=ent(id.split('-')[0]),s=o&&(o.services||[]).find(x=>x.id===id);if(!s)return null;return {id:s.id,name:{en:s.n,hi:s.n},emoji:o.emoji,hue:o.hue,cat:s.cat,sub:s.sub,rating:o.rating,rc:o.rc,status:o.status,lat:o.lat,lng:o.lng,phone:o.phone,wa:o.wa,area:o.area,addr:o.addr,hours:o.hours,closedNow:o.closedNow,verified:o.verified,serviceArea:o.serviceArea,gallery:o.gallery,since:o.since,desc:s.desc,svc:s,owner:o}}
const svOffer=s=>D().offers.find(o=>o.status==='active'&&Date.now()<o.to&&(o.sids||[]).includes(s.id));
const svPrice=s=>{if(s.ptype==='enquiry')return t('Price on enquiry');if(s.ptype==='free')return t('Free');const u=s.unit?' '+s.unit.replace(/^\/\s*/,'/ '):'';return (s.ptype==='from'?t('from')+' ':'')+inr(s.from)+u};
function serviceCard(s){const o=s.owner||ent(s.oid),d=dist(o),of=svOffer(s),op=openState(o),bm=isBm(s.id);
 return `<article class="card hover shopcard" aria-label="${esc(s.n)}"><a class="cover" data-lazy href="#service-${s.id}" aria-label="${esc(s.n)}">${art(o.emoji,o.hue,'f')}${of?`<span class="badge offer" style="position:absolute;left:8px;top:8px;background:var(--surface)">${ic('tag',12)} ${esc(of.type==='percent'?of.value+'% '+t('OFF'):of.type==='flat'?'₹'+of.value+' '+t('OFF'):t('Offer'))}</span>`:''}</a><div class="body"><div class="row wrap-r" style="gap:6px"><span class="badge sec">${esc(subLabel(s.sub)||catName(s.cat))}</span>${op.open?`<span class="badge ok">● ${t('Open now')}</span>`:`<span class="badge neu">○ ${esc(op.label)}</span>`}</div><a href="#service-${s.id}" class="bold" style="font-size:1rem;line-height:1.3">${esc(s.n)}</a><a class="row" href="#${o.id[0]==='s'?'svc':'biz'}-${o.id}" style="gap:8px"><span class="art" style="--h:${o.hue};width:26px;height:26px;border-radius:50%;font-size:.9rem;aspect-ratio:auto">${o.emoji}</span><span class="small t2 truncate">${esc(nm(o.name))}</span>${o.verified?`<span title="${t('Verified')}" style="color:var(--secondary)">${ic('shield',14)}</span>`:''}</a><div><b class="price">${svPrice(s)}</b></div><div class="meta small">${stars(o.rating)}<b>${o.rating.toFixed(1)}</b><span class="muted">(${o.rc})</span><span>·</span><span>${ic('pin',12)} ${d.toFixed(1)} km</span></div><div class="acts"><a class="btn g" href="${telH(o.phone)}" aria-label="${t('Call')} ${esc(nm(o.name))}">${ic('phone',16)}</a><a class="btn g" target="_blank" rel="noopener" href="${waH(o.wa,'Hi, I saw '+s.n+' on ApnaTown')}" aria-label="WhatsApp">${ic('chat',16)}</a><button class="btn g" data-act="bm" data-id="${s.id}" aria-pressed="${bm}" aria-label="${t('Save')}">${ic('bookmark',16)}</button><a class="btn p" href="#service-${s.id}">${t('View')}</a></div></div></article>`}
/* services filter component now counts individual services */
function svcBaseList(f){let l=allServices();if(f.dist)l=l.filter(x=>dist(x.owner)<=f.dist);if(f.rating)l=l.filter(x=>x.owner.rating>=f.rating);if(f.avail)l=l.filter(x=>openState(x.owner).open);if(f.verified)l=l.filter(x=>x.owner.verified);if(f.offers)l=l.filter(x=>svOffer(x));if(f.enq)l=l.filter(x=>x.ptype==='enquiry');if(f.pmin!==''&&f.pmin!==undefined)l=l.filter(x=>x.from>=+f.pmin);if(f.pmax!==''&&f.pmax!==undefined)l=l.filter(x=>x.ptype==='enquiry'||x.from<=+f.pmax);return l}
function svcApplyCS(l,f){if((f.cats||[]).length)l=l.filter(x=>f.cats.includes(x.cat));if((f.subs||[]).length)l=l.filter(x=>f.subs.includes(x.sub));return l}
function exServices(){const f=UI.exF.s;if(UI.exCat&&!f.cats.length&&!SCATS.some(c=>c.id===UI.exCat))return[];let l=svcApplyCS(svcBaseList(f),f);const so=f.sort;if(so==='rating')l.sort((a,b)=>b.owner.rating-a.owner.rating);else if(so==='distance')l.sort((a,b)=>dist(a.owner)-dist(b.owner));else if(so==='price')l.sort((a,b)=>(a.ptype==='enquiry'?1e9:a.from)-(b.ptype==='enquiry'?1e9:b.from));else l.sort((a,b)=>(!!svOffer(b)-!!svOffer(a))||dist(a.owner)-dist(b.owner));return l}
const sfBase=ctx=>ctx==='srch'?srchServicesBase():ctx==='ex'?svcBaseList(UI.exF.s):allServices();
function catResHtml(id){const f=UI.cf,l=svcApplyCS(allServices().filter(s=>s.cat===id),f).sort((a,b)=>dist(a.owner)-dist(b.owner));const chips=f.subs;
 return `<div class="row between wrap-r"><b aria-live="polite">${l.length} ${t('services')}</b>${chips.length?`<button class="btn t sm" data-act="cfClear">${t('Clear all')}</button>`:''}</div>${chips.length?`<div class="row wrap-r" style="gap:6px">${chips.map(x=>`<button class="rchip" data-act="cfRm" data-s="${x}" aria-label="${t('Remove filter')}: ${esc(subLabel(x))}">${esc(subLabel(x))} <b>${ic('x',14)}</b></button>`).join('')}</div>`:''}${l.length?`<div class="shopgrid">${l.map(serviceCard).join('')}</div>`:empty('🔎','No services match','Try removing a subcategory.','<button class="btn p" data-act="cfClear">'+t('Clear all')+'</button>')}`}
